parameters.functionCode:
const body = $json || {};

const synologyRoot = body.synologyRoot || 'C:\\Users\\info\\SynologyDrive';
const projectRoot = body.projectRoot || `${synologyRoot}\\crimson-nadir`;
const n8nBaseUrl = body.n8nBaseUrl || 'http://localhost:5678/api/v1';
const apiKey = body.n8nApiKey || $env.N8N_API_KEY || '';

return [{
  json: {
    user: body.user || 'Emma',
    os: 'windows',
    synologyRoot,
    projectRoot,
    n8n: {
      baseUrl: n8nBaseUrl,
      apiKey,
      webhookPath: 'emma-antigravity-fusion'
    },
    repos: {
      skills: 'https://github.com/sickn33/antigravity-awesome-skills',
      cleaner: 'https://github.com/tawroot/antigravity-cleaner',
      claudeCode: 'https://github.com/anthropics/claude-code',
      claudeCliFork: 'https://github.com/clouitreee/claude-code-CLI'
    }
  }
}];

const j = $json;
const missing = [];
if (!j.n8n?.baseUrl) missing.push('n8n.baseUrl');
if (!j.n8n?.apiKey) missing.push('n8n.apiKey');

return [{
  json: {
    ...j,
    validation: {
      ok: missing.length === 0,
      missing
    }
  }
}];

const j = $json;
const statusCode = j.statusCode || j.code || null;
const probeOk = !!(j.statusCode && j.statusCode >= 200 && j.statusCode < 300);

return [{
  json: {
    ...j,
    probe: {
      ok: probeOk,
      statusCode: statusCode,
      note: probeOk ? 'n8n API erreichbar' : 'n8n API nicht erreichbar oder Auth fehlgeschlagen'
    }
  }
}];

const j = $json;

const powerShellSetup = [
  `$synology = "${j.synologyRoot}"`,
  `$project = "${j.projectRoot}"`,
  'New-Item -ItemType Directory -Force -Path $project | Out-Null',
  'Set-Location $project',
  'irm https://claude.ai/install.ps1 | iex',
  'npx -y antigravity-awesome-skills --path ~/.codex/skills',
  'npx -y antigravity-awesome-skills --path ~/.claude/skills',
  'iwr https://raw.githubusercontent.com/tawroot/antigravity-cleaner/main/install.ps1 -useb | iex'
].join('\n');

const bridgeWorkflow = {
  name: 'EMMA_N8N_API_BRIDGE',
  nodes: [
    {
      parameters: { path: 'emma-n8n-api-bridge', method: 'POST', responseMode: 'responseNode', options: {} },
      id: 'bridge-webhook',
      name: 'Bridge Webhook',
      type: 'n8n-nodes-base.webhook',
      typeVersion: 1,
      position: [240, 280]
    },
    {
      parameters: { functionCode: 'return [{ json: { status: "ok", source: "EMMA_N8N_API_BRIDGE", input: $json } }];' },
      id: 'bridge-function',
      name: 'Bridge Function',
      type: 'n8n-nodes-base.function',
      typeVersion: 1,
      position: [460, 280]
    },
    {
      parameters: { respondWith: 'json', responseBody: '={{$json}}', options: {} },
      id: 'bridge-respond',
      name: 'Bridge Respond',
      type: 'n8n-nodes-base.respondToWebhook',
      typeVersion: 1,
      position: [680, 280]
    }
  ],
  connections: {
    'Bridge Webhook': { main: [[{ node: 'Bridge Function', type: 'main', index: 0 }]] },
    'Bridge Function': { main: [[{ node: 'Bridge Respond', type: 'main', index: 0 }]] }
  },
  active: false,
  settings: { executionOrder: 'v1' }
};

const createBridgeCmd = [
  '$headers = @{"X-N8N-API-KEY" = "<N8N_API_KEY>"; "Content-Type" = "application/json"}',
  `$body = @'${JSON.stringify(bridgeWorkflow, null, 2)}'@`,
  `Invoke-RestMethod -Method POST -Uri "${j.n8n.baseUrl}/workflows" -Headers $headers -Body $body`
].join('\n');

return [{
  json: {
    ...j,
    artifacts: {
      emmaSystemPrompt: [
        'Du bist EMMA auf Synology.',
        `Projektpfad: ${j.projectRoot}`,
        'Priorität: n8n API zuerst, danach lokale Agenten-Tools.'
      ].join('\n'),
      powerShellSetup,
      n8nProbe: j.probe,
      createBridgeCmd,
      bridgeWorkflow
    }
  }
}];
